import React from 'react';
import { Routes, Route } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import Navbar from './components/Navbar';
import HomePage from './pages/HomePage';
import './pages/HomePage.css';
import './components/Navbar.css';
import './styles/globals.css';

function App() {
  return (
    <AuthProvider>
      <Navbar />
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/login" element={<div style={{ padding: '50px', textAlign: 'center' }}>Login Page - Coming Soon</div>} />
        <Route path="/register" element={<div style={{ padding: '50px', textAlign: 'center' }}>Register Page - Coming Soon</div>} />
        <Route path="/browse" element={<div style={{ padding: '50px', textAlign: 'center' }}>Browse Pets - Coming Soon</div>} />
      </Routes>
    </AuthProvider>
  );
}

export default App;
